from book import Chapter
c=Chapter('17')
c.src('SEED-R14-0',0,replacements=[('事实上，我的设想比你提到的更进一步，不是只具有随时收回数据的能力','我的设想，不只停留在随时收回数据的能力上'),('生产设计运营','生产、设计、运营')])
c.heading('谁拥有对 AI 掌控权的控制权')
c.src('R46622',0,end='这种权力的不对等导致了利益分配，包括在决策上的不对等。',replacements=[('现在最需要解决的，我认为是','我认为最需要解决的是'),('现在呢，不管是开源的也好，闭源的也好，背后的实体都是传统的这种公司。不管规模大小，其权力结构还都是传统的社会组织形式','如果一个 AI 无论开源还是闭源，背后的运营实体仍是传统公司，权力结构仍是传统的社会组织形式'),('就是金字塔式的','也就是金字塔式的')])
c.add('''开源可以使我们看见程序怎样工作，也可以使有能力的人修改它。但能够读到代码，与能够决定这项服务怎样收费、资料怎样使用、资源优先给谁，还不是同一回事。一个用户也许能够把程序下载下来，却没有足够的设备运行；一个开发者也许能够修改代码，却不能改变运营平台上的规则。

如果这些条件始终掌握在少数人手里，那么公开一份代码，并没有完成对整个组织关系的改变。新体制所要开放的，是从知识到产品、从产品到服务、再到服务的组织和决策这一整条链条。''')
c.src('R46622',0,start='而我说的这个架构最大的优势',replacements=[('而我说的这个架构最大的优势就是利用 Mochow架构','我所设想的这个架构，要利用 Merkle 架构'),('对 AI模型的控制掌握在我说的这种动态分配权重，所有博弈当中整个所有参与构建 AI的这些用户节点之间是权力对等、公平博弈的这样一个组织','对 AI 模型的控制，由参与构建和使用它的人共同掌握，形成动态分配权重、节点之间地位对等的组织'),('这样的话没有任何一个人会担心，因为这个 AI 实际上它就是属于每一个用户自身，就是这个 OAI控制权中的一个','这样，这个 AI 就属于共同参与的用户，每一个人都是其控制权的参与者'),('他不用担心其他的节点会具有不公平的权力差距，来操控 AI，对自己做出有损失或者有害的行为的这种事情','我们所要消除的，是其他节点凭借不对等的权力操控 AI、损害自己的那种组织条件'),('所以我觉着','所以我觉得'),('这样的话我们就不用担心这个 AI的控制者会利用 AI对自己做任何不利的事情','这样的组织，要使 AI 的能力与每一个参与者的利益联系起来')])
c.heading('消费者为什么也可以成为生产者')
c.src('R34488',0,end='或者提供测试反馈。',replacements=[('越是大型的复杂系统，往往越是基于git的开源软件越有优势','大型复杂系统的开发，可以使我们看到开源协作的一种重要优势'),('无法匹敌开放源代码的项目的贡献者可以覆盖全球范围的任何一个感兴趣的用户','而开放源代码项目的贡献者，可以来自全球范围内感兴趣的用户'),('私营公司的软件开发范式，开发者仅限于公司内部员工','以公司内部团队为中心的开发范式，首先受限于这个团队已经具备的能力和组织边界'),('开发者就是全体用户','用户也可以成为开发过程的参与者')])
c.add('''这使“生产者”和“消费者”不再是永远分开的两群人。一个人没有编程经验，但他知道这个工具在自己的生活里哪里不好用；另一个人熟悉某种语言，可以帮助更多人理解；还有一个人能够复现故障，把原来模糊的抱怨变成开发者可以解决的问题。这些工作，都参与了产品的形成。

因此，参与不应当只有一种被认可的形式，也不应该变成使用产品之前必须完成的义务。有些人愿意投入大量时间，有些人只能提供少量反馈，还有些人在某一阶段只需要安稳地使用服务。组织应当容纳这些不同的参与方式。''')
c.src('SEED-R14-0',2,replacements=[('当然跟众筹有一些不同','这样的参与方式，跟通常的众筹有一些不同'),('最便宜最简单','最简单、成本能够承担'),('个人的小资金零钱','个人能够承担的小笔资金')])
c.heading('共享贡献，怎样避免贡献者被抹掉')
c.src('R34488',0,start='而且基于git的开源软件的参与者',replacements=[('其贡献大小都可以精确量化','其提交、修改和讨论过程可以被清楚记录'),('代码编写以及提交的issue的数量','代码修改和问题反馈等记录'),('可以非常精确的计算出，一个软件的所有贡献者的精确贡献比例','可以把一个软件的形成过程及其参与者，更细致地保留下来'),('来计算贡献值','来考察贡献'),('但是这样的分配方式显然更公平','这种能够保留来源和协作过程的方式，为更公平地承认贡献提供了基础')])
c.add('''这里还需要把“记录清楚”与“判断价值”分开。修好一个关键错误可能只改了一行代码，制造一个不必要的复杂功能却可能写了几千行。有人提出了问题，有人找到了错误假设，有人写了实现，有人提供了第一次真实使用反馈。只按代码行数或者发言次数计算，就会把很不相同的贡献混成一个数字。

所以，完整记录的意义，是让这些关系能够被重新考察。一个结论借用了谁的材料，一个程序依赖了谁的实现，一次失败为什么使后来的方向发生改变，都应该可以追溯。贡献的解释也可以随着认识的深入而修正，而不是只能接受最早宣布成果的人所写下的名单。''')
c.src('R34488',1,replacements=[('将这个软件开发领域的方式，如果进一步推广到人类的全部智力活动中呢','如果把软件开发中的这种方式，进一步推广到人类更广泛的智力活动中呢'),('它就能够记录每一个人对这个文明系统的精确贡献值','它就能够为每个人对这个文明系统的贡献留下可追溯的依据'),('是影响整个系统进化的最大因素','是影响整个系统进化的重要因素'),('是不同个人，团体互相充分合作，实现最高效率发展的最大障碍','会阻碍不同个人和团体充分合作'),('彼此之间对等的信息透明贡献，是最好的解决办法','彼此能够对等地分享信息、承认贡献，是值得构建的一条解决路径'),('获得贡献值的精确统计','获得更完整的贡献记录和可继续讨论的评价依据')])
c.heading('从品牌之间的竞争，走向共同构造产品')
c.src('R54910',13,replacements=[('另外，有了这个语义归一化的Merkle-DAG框架的文明DNA架构','在能够对齐语义、追踪来源和实现的 Merkle-DAG 框架中'),('都会大幅提高','就有机会得到提高'),('以后再也没企业之间低效甚至恶意的竞争来消耗不必要的资源','这样可以减少企业之间低效甚至恶意的竞争所消耗的资源'),('让资本家剥削这件事彻底告别人类的经济生活','这也是我希望剥削能够退出人类经济生活的一条实践方向'),('以后的人类社会不需要过去那种金字塔结构的的大公司和政府机关','我所追求的，是让人类社会逐渐不再依赖那种具有巨大权力落差的金字塔组织')])
c.add('''手机的例子可以再往下想一步。有人改进了某个传感器，有人优化了一个功能，有人发现一种组合更适合老年人使用。如果这些改进都必须先被某个品牌收购、包装，再经过一次完整的产品周期才能进入用户生活，许多可以独立传播的改进，就被捆在了组织边界里。

如果产品能够用可组合的功能和条件来描述，那么一项改进就可以在符合条件的地方被采用。不同实现可以并存，使用者可以按照自己的需要选择，创造者的贡献也可以沿着依赖关系被保留下来。共同规范因此可以扩大多样性：大家不必先重复建造整座工厂，才有资格改好其中一个零件。''')
c.heading('规模扩大为什么不应该变成新的垄断')
c.src('SEED-R14-0',1,start='在这个全过程中',end='按新体制进行公平的分配和决策。',replacements=[('动态权重决智能网络系统','动态权重决策的智能网络系统'),('防篡改','使篡改能够被核验'),('如果你真的理解我说的新体制，这种扩张兼并和改造，不会产生旧体制下的那种垄断现象，相反','按照这个方向设计扩张、兼并和改造，所追求的效果与旧体制下的垄断不同'),('从而让新制度，产生与垄断截然相反的效果，极大的推动了科学技术和生产力的进步','从而有机会产生与垄断相反的效果，推动科学技术和生产力的进步')])
c.add('''判断这一点，需要看规模增长时究竟发生了什么。如果加入的人越多，创始人能够任意决定的事情也越多，那么扩大的是旧式权力。如果加入的人越多，共同的知识、设备和服务能力越强，而每个参与者仍能理解规则、参与修改、保留自己的资料和选择，那么增长才与最初的方向一致。

这也是为什么组织的开放必须从一个人时就开始。共同记录、公开规则和保留来源，并不是等到规模很大之后再加上的装饰。它们决定了一个人的试验在长成多人组织时，会沿着什么方式继续生长。

而对第一个参与者来说，最直接的起点，就是先拿回自己的数据和工具。只有个人不再被锁在别人的信息孤岛里，新的合作关系才有真正可以连接起来的节点。''')
c.save({'central_question':'为什么产品开源还不足以完成组织关系的改变','reasoning':'服务控制权→广泛参与→贡献记录与评价分离→功能组合→规模增长与共同控制→个人主权','examples':['能读代码但不能决定服务','报告故障和语言贡献','一行修复与千行冗余','手机功能模块'],'objections':['开源代码即开放治理','不写代码就不生产','提交数量等于贡献价值','扩大规模必然产生原式垄断'],'voice':'保留作者全面开源、消费者生产者、贡献追踪、手机与从一人开始的论述','status':'已初校；具体组织制度继续通过实践章节展开'})
